use buggy_service::PricingEngine;

fn main() {
    let mut engine = PricingEngine::new(1.0);
    engine.update_configuration(1.5);
    if engine.trace_is_fresh() {
        println!("trace 212: configuration propagated to quote state");
    } else {
        eprintln!("trace 212: source_rate=1.5 cached_rate=1.0");
        std::process::exit(212);
    }
}

pub struct PricingEngine {
    source_rate: f64,
    cached_rate: f64,
}

impl PricingEngine {
    pub fn new(rate: f64) -> Self {
        Self { source_rate: rate, cached_rate: rate }
    }

    pub fn update_configuration(&mut self, rate: f64) {
        self.source_rate = rate;
    }

    pub fn quote(&self, base: f64) -> f64 {
        base * self.cached_rate
    }

    pub fn trace_is_fresh(&self) -> bool {
        self.source_rate == self.cached_rate
    }
}

use buggy_service::PricingEngine;

#[test]
fn production_sequence_is_no_longer_reproducible() {
    let mut engine = PricingEngine::new(0.8);
    engine.update_configuration(1.2);
    assert_eq!(engine.quote(250.0), 300.0);
    assert!(engine.trace_is_fresh());
}

